// Screenshots einer Seite in mehreren Breiten, sammelt Konsolenfehler.
// Aufruf: node shot.mjs <url> <ausgabeordner> [breiten, z. B. 1440,768,390] [--full | --tiles | --el=<css>]
//   --el=<css> jedes passende Element einzeln aufnehmen, z. B. --el=[data-abschnitt=hero]
//   --full   eine Ganzseiten-Aufnahme (Reveal-Inhalte werden vorher sichtbar gemacht)
//   --tiles  eine Aufnahme je Bildschirmhöhe beim echten Scrollen (wie ein Mensch sieht)
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const [url, out = "./shots", breitenArg = "1440,390", ...rest] = process.argv.slice(2);
const full = rest.includes("--full");
const tiles = rest.includes("--tiles");
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
for (const w of breitenArg.split(",").map(Number)) {
  const h = w < 700 ? 844 : 900;
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const fehler = [];
  page.on("console", (m) => m.type() === "error" && fehler.push(m.text()));
  page.on("pageerror", (e) => fehler.push(String(e)));
  await page.goto(url, { waitUntil: "networkidle", timeout: 120000 });
  await page.waitForTimeout(600);
  // Cookie-Banner schließen, damit er keine Inhalte verdeckt
  await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(400);
  const gesamt = await page.evaluate(() => document.documentElement.scrollHeight);

  const elArg = rest.find((a) => a.startsWith("--el="));
  if (elArg) {
    // einzelne Elemente (z. B. --el=[data-abschnitt=hero]) nacheinander ins Bild scrollen und aufnehmen
    const sel = elArg.slice(5);
    const els = await page.locator(sel).all();
    if (!els.length) console.log(`  ! kein Element für ${sel}`);
    let n = 0;
    for (const el of els) {
      await el.scrollIntoViewIfNeeded();
      // langsam durch das Element scrollen, damit Reveal-Inhalte sichtbar werden
      const box = await el.boundingBox();
      if (box) for (let d = 0; d < box.height; d += 300) { await page.mouse.wheel(0, 300); await page.waitForTimeout(100); }
      await page.waitForTimeout(900);
      const name = sel.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "");
      const datei = `${out}/w${w}-${name}${els.length > 1 ? "-" + n : ""}.png`;
      n++;
      await el.screenshot({ path: datei });
      console.log(datei);
    }
  } else if (tiles) {
    let n = 0;
    for (let y = 0; y < gesamt; y += h - 80) {
      await page.evaluate((yy) => window.scrollTo(0, yy), y);
      await page.waitForTimeout(900);
      const datei = `${out}/w${w}-${String(n++).padStart(2, "0")}.png`;
      await page.screenshot({ path: datei });
      console.log(datei);
    }
  } else {
    // langsam durchscrollen, damit Reveal-Beobachter auslösen
    for (let y = 0; y < gesamt; y += 300) { await page.evaluate((yy) => window.scrollTo(0, yy), y); await page.waitForTimeout(120); }
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(800);

import { Plus } from "lucide-react";
import { cn } from "./cn";

/**
 * FAQ-Akkordeon auf Basis von <details> – funktioniert ohne JavaScript,
 * ist per Tastatur bedienbar und liefert optional FAQPage-Schema.
 * items: [{ q, a }]  (a: String oder JSX; für Schema wird `aText` oder a als String genutzt)
 */
export default function Faq({ items = [], schema = true, className, tone = "light" }) {
  const dunkel = tone === "dark";
  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((it) => ({
      "@type": "Question",
      name: it.q,
      acceptedAnswer: { "@type": "Answer", text: it.aText || (typeof it.a === "string" ? it.a : "") },
    })),
  };

  return (
    <div className={cn("divide-y", dunkel ? "divide-white/10" : "divide-ink-200", className)}>
      {schema && items.length > 0 && (
        <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }} />
      )}
      {items.map((it, i) => (
        <details key={it.q} className="group py-1" open={i === 0 ? undefined : undefined}>
          <summary
            className={cn(
              "flex cursor-pointer list-none items-center justify-between gap-6 py-5 text-left font-display text-[17px] font-bold leading-snug transition-colors md:text-[18.5px] [&::-webkit-details-marker]:hidden",
              dunkel ? "text-white hover:text-ov-300" : "text-ink-900 hover:text-ov-700"
            )}
          >
            {it.q}
            <span
              className={cn(
                "flex h-9 w-9 shrink-0 items-center justify-center rounded-full transition-all duration-300 group-open:rotate-45",
                dunkel ? "bg-white/10 text-white group-open:bg-ov-500" : "bg-ink-100 text-ink-700 group-open:bg-ov-500 group-open:text-white"
              )}
            >
              <Plus aria-hidden="true" className="h-4 w-4" />
            </span>
          </summary>
          <div className={cn("-mt-1 pb-6 pr-12 text-[16px] leading-relaxed", dunkel ? "text-white/70" : "text-ink-600")}>
            {it.a}
          </div>
        </details>
      ))}
    </div>
  );
}
import Link from "next/link";
import { ArrowUpRight, Phone, Calculator, ShieldCheck, Clock, BadgeCheck } from "lucide-react";
import { KONTAKT } from "@/data/site";
import { cn } from "./cn";
import Button from "./Button";
import Reveal from "./Reveal";

/**
 * Abschluss-Handlungsaufruf für jede Seite. Dunkle, leuchtende Fläche mit
 * zwei Wegen und einer Wegweiser-Box für die Zielgruppen. Telefon erscheint
 * nur, wenn in src/data/site.js eine Nummer hinterlegt ist.
 */
export default function CtaBand({
  eyebrow = "Kostenlos & unverbindlich",
  title = "Ihre Fläche, Ihr Projekt, Ihr Kapital – wir machen daraus ein Kraftwerk.",
  text = "Ein Team, das seit 2010 Solarkraftwerke plant, baut und selbst betreibt. Mit ehrlicher Ersteinschätzung, festem Ansprechpartner und transparentem Status im Portal.",
  primary = { label: "Fläche prüfen lassen", href: "/flaechencheck" },
  secondary = { label: "Zur Projektbörse", href: "/projektboerse" },
  className,
}) {
  return (
    <section className={cn("relative px-4 py-16 md:px-8 md:py-24", className)}>
      <Reveal dir="scale" className="ov-noise relative mx-auto max-w-7xl overflow-hidden rounded-[2rem] bg-navy-950 px-6 py-14 text-white md:rounded-[2.5rem] md:px-16 md:py-20">
        <div aria-hidden="true" className="ov-grid-bg absolute inset-0" />
        <div aria-hidden="true" className="absolute -right-24 -top-32 h-[460px] w-[460px] rounded-full bg-ov-500/35 blur-[110px]" />
        <div aria-hidden="true" className="absolute -bottom-40 left-1/4 h-[360px] w-[360px] rounded-full bg-sun-400/15 blur-[110px]" />

        {/* minmax(0, …): Spalten dürfen nicht über ihren Anteil wachsen – sonst schieben breite Buttons
            die rechte Box in den Innenabstand und overflow-hidden schneidet sie ab */}
        <div className="relative grid items-center gap-12 lg:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]">
          <div className="min-w-0">
            <p className="text-[12.5px] font-semibold uppercase tracking-[0.16em] text-ov-300">{eyebrow}</p>
            <h2 className="ov-h2 mt-4 text-white">{title}</h2>
            <p className="ov-lead mt-5 max-w-2xl text-white/70">{text}</p>
            {/* flex-wrap: bei wenig Platz rutscht der zweite Button in die nächste Zeile */}
            <div className="mt-9 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
              <Button href={primary.href} size="lg" pfeil>
                {primary.label}
              </Button>
              {secondary && (
                <Button href={secondary.href} size="lg" variant="outlineLight" icon={secondary.icon === undefined ? undefined : secondary.icon}>
                  {secondary.label}
                </Button>
              )}
            </div>
          </div>

          <div className="ov-glass min-w-0 rounded-3xl p-6 md:p-8">
            {KONTAKT.telefon ? (
              <>
                <p className="text-[13px] font-medium text-white/60">Lieber direkt sprechen?</p>
                <a href={KONTAKT.telefonHref} className="group mt-2 flex items-center gap-3">
                  <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-ov-500 transition-transform group-hover:scale-110">
                    <Phone aria-hidden="true" className="h-5 w-5" />
                  </span>
                  <span className="min-w-0 font-display text-[22px] font-extrabold tracking-tight md:text-[26px]">{KONTAKT.telefon}</span>
                </a>
              </>
            ) : (
              <>
                <p className="text-[13px] font-medium text-white/60">Direkt zum passenden Weg</p>
                <ul className="mt-3 grid gap-2">
                  {[
                    { label: "Ich habe eine Fläche", href: "/flaeche-verpachten" },
                    { label: "Ich bin Landwirt", href: "/landwirte" },
                    { label: "Ich möchte investieren", href: "/investoren" },
                    { label: "Ich brauche günstigen Strom", href: "/reststrom" },
                  ].map((w) => (
                    <li key={w.href}>
                      <Link href={w.href} className="group flex items-center justify-between gap-3 rounded-2xl bg-white/[0.06] px-4 py-3 text-[15px] font-semibold ring-1 ring-white/10 transition-colors hover:bg-white/[0.12]">
                        {w.label}
                        <ArrowUpRight aria-hidden="true" className="h-4 w-4 text-ov-300 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
                      </Link>
                    </li>
                  ))}
                </ul>
              </>
            )}
            <ul className="mt-6 space-y-3 border-t border-white/10 pt-6 text-[14.5px] text-white/80">
              <li className="flex items-start gap-2.5"><BadgeCheck aria-hidden="true" className="mt-[3px] h-4 w-4 shrink-0 text-ov-300" /><span className="min-w-0">Teil der ÖKOVOLT Gruppe – seit 2010 im Solargeschäft</span></li>
              <li className="flex items-start gap-2.5"><ShieldCheck aria-hidden="true" className="mt-[3px] h-4 w-4 shrink-0 text-ov-300" /><span className="min-w-0">Entwicklung, Bau und Betrieb aus einer Gruppe</span></li>
              <li className="flex items-start gap-2.5"><Clock aria-hidden="true" className="mt-[3px] h-4 w-4 shrink-0 text-ov-300" /><span className="min-w-0">Status, Dokumente und Nachrichten im Portal</span></li>
            </ul>
          </div>
        </div>
      </Reveal>
    </section>
  );
}
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";

import Reveal from "@/components/ui/Reveal";

/**
 * Thematische Querverweise am Ende einer Seite.
 *
 * Zweck ist nicht Dekoration, sondern Struktur: Vor dieser Komponente hatte
 * praktisch keine Seite einen redaktionellen Eingangslink – jede war nur
 * ueber das Menue erreichbar. Jede Seite uebergibt 2–4 kuratierte Ziele
 * mit sprechendem Ankertext: items=[{ href, titel, text }].
 *
 * Rendert nichts, wenn keine Verweise uebergeben werden.
 */
export default function Querverweise({ items = [], ueberschrift = "Das könnte Sie auch interessieren" }) {
  const verweise = items;
  if (verweise.length === 0) return null;

  return (
    <section aria-labelledby="querverweise-titel" className="bg-white">
      <div className="ov-container py-16 md:py-20">
        <div className="mb-8 flex items-end justify-between gap-6 border-b border-ink-200 pb-6">
          <h2 id="querverweise-titel" className="ov-h3 text-ink-900 md:text-[28px]">
            {ueberschrift}
          </h2>
        </div>

        <ul className={`grid gap-4 sm:grid-cols-2 ${verweise.length === 4 ? "lg:grid-cols-4" : "lg:grid-cols-3"}`}>
          {verweise.map((v, i) => (
            <Reveal as="li" key={v.href} delay={i * 70} className="flex">
              <article className="group ov-card-hover relative flex w-full flex-col rounded-3xl bg-sand-50 p-6 ring-1 ring-ink-200/60 focus-within:ring-2 focus-within:ring-ov-500 hover:bg-white">
                <span className="mb-6 flex h-10 w-10 items-center justify-center rounded-full bg-white text-ink-400 ring-1 ring-ink-200 transition-all duration-300 group-hover:bg-ov-500 group-hover:text-white group-hover:ring-ov-500">
                  <ArrowUpRight aria-hidden="true" className="h-4 w-4 transition-transform duration-300 group-hover:rotate-45" />
                </span>
                <h3 className="font-display text-[18px] font-bold leading-snug text-ink-900">
                  {/* Stretched Link: genau EIN Link je Karte auf die Ziel-URL. */}
                  <Link href={v.href} className="outline-none after:absolute after:inset-0 after:rounded-3xl after:content-['']">
                    {v.titel}
                  </Link>
                </h3>
                <p className="mt-2 text-[15px] leading-relaxed text-ink-600">{v.text}</p>
              </article>
            </Reveal>
          ))}
        </ul>
      </div>
    </section>
  );
}
import { cn } from "./cn";

const TOENE = {
  white: "bg-white text-ink-900",
  sand: "bg-sand-50 text-ink-900",
  ink: "bg-ink-50 text-ink-900",
  green: "bg-ov-50 text-ink-900",
  navy: "bg-navy-950 text-white",
};

const ABSTAENDE = {
  none: "",
  sm: "py-12 md:py-16",
  md: "py-16 md:py-24",
  lg: "py-20 md:py-32",
};

/**
 * Seitenabschnitt mit einheitlichem Rhythmus.
 * tone: white | sand | ink | green | navy
 * space: none | sm | md | lg
 */
export default function Section({
  tone = "white",
  space = "md",
  id,
  className,
  containerClassName,
  bare = false,
  as: Tag = "section",
  children,
  ...rest
}) {
  return (
    <Tag
      id={id}
      className={cn("relative", TOENE[tone], ABSTAENDE[space], className)}
      {...rest}
    >
      {bare ? children : <div className={cn("ov-container relative", containerClassName)}>{children}</div>}
    </Tag>
  );
}

export function Container({ className, children }) {
  return <div className={cn("ov-container", className)}>{children}</div>;
}
import { cn } from "./cn";
import Reveal from "./Reveal";

/**
 * Kleine Überzeile über Headlines.
 * Der Punkt sitzt in einer Box mit genau einer Zeilenhöhe – einzeilig mittig zum Text,
 * bei Umbruch mittig zur ersten Zeile.
 */
export function Eyebrow({ children, dark = false, className }) {
  return (
    <p
      className={cn(
