    rest: "Die Marktpartner-ID gehört der Gemeinschaft; wir erhalten einen Zugang im EDA-Anwenderportal bzw. eine Bevollmächtigung. Die bestehenden Zustimmungen der Mitglieder bleiben gültig. Für einen Monat rechnen wir parallel und gleichen mit den Werten des Netzbetreibers ab.",
    mehr: { href: "#wechsel", label: "So läuft der Wechsel ab" },
  },
  {
    id: "faq-ersparnis",
    thema: "Ersparnis",
    icon: PiggyBank,
    q: "Wie hoch ist die Ersparnis für ein Mitglied?",
    kurz: "Das hängt vom Modell, vom Verbrauchsprofil und vom Preis in der Gemeinschaft ab.",
    rest: "Öffentlich genannte Beispiele liegen bei rund 50 bis 200 € im Jahr je Haushalt. Der Rechner oben zeigt Ihre Größenordnung – die Netzentgelt-Reduktion zieht der Netzbetreiber direkt auf der Netzrechnung ab.",
    mehr: { href: "#rechner", label: "Zum Rechner" },
  },
  {
    id: "faq-netzentgelte",
    thema: "Netzentgelte",
    icon: Scale,
    q: "Was passiert bei den Netzentgelten ab 2027?",
    kurz: "Mit dem ElWG sollen reduzierte Netzentgelte künftig nach dem Nahebereich (Zonelevel) statt nach der Form der Gemeinschaft berechnet werden.",
    rest: "Die neue Verordnung lag zum 1. Oktober 2026 noch nicht endgültig vor; wir rechnen bis dahin mit einer gekennzeichneten Arbeitshypothese und passen die Werte an, sobald sie feststehen.",
    mehr: { href: "#elwg", label: "Mehr zum ElWG" },
  },
  {
    id: "faq-kosten",
    thema: "Kosten",
    icon: ReceiptText,
    q: "Was kostet die Plattform?",
    kurz: "Wir kalkulieren je Gemeinschaft nach Paket und Größe und legen das Angebot offen dar.",
    rest: "Fragen Sie unverbindlich an – mit wenigen Angaben zu Mitgliedern und Anlagen erhalten Sie ein konkretes Angebot.",
    mehr: { href: "#pakete", label: "Pakete ansehen" },
  },
  {
    id: "faq-datenschutz",
    thema: "Datenschutz",
    icon: ShieldCheck,
    q: "Wer sieht die Viertelstundenwerte der Mitglieder?",
    kurz: "Mitglieder sehen ihre eigenen Werte.",
    rest: "Vorstand und Kassa sehen standardmäßig Summen; eine Einzeleinsicht ist nur mit Zweck möglich und wird protokolliert. Die Betriebsführung arbeitet im Auftrag der Gemeinschaft (Auftragsverarbeitung nach Art. 28 DSGVO).",
  },
];

const SCHEMA = {
  "@context": "https://schema.org",
  "@type": "FAQPage",
  mainEntity: FAQ.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: `${f.kurz} ${f.rest}` } })),
};

export default function Faq() {
  return (
    <Section data-abschnitt="faq" tone="white" space="lg" aria-labelledby="faq-titel">
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(SCHEMA) }} />
      <div className="grid gap-10 lg:grid-cols-[minmax(0,0.85fr)_minmax(0,1.15fr)] lg:gap-20">
        <div className="lg:sticky lg:top-28 lg:self-start">
          <SectionHeading eyebrow="Häufige Fragen" title={<span id="faq-titel">Was Vorstände vor dem Start fragen</span>} lead="Sechs Antworten zu Modellen, Wechsel, Ersparnis, Netzentgelten, Kosten und Datenschutz – jeweils mit der Kurzantwort zuerst." />

          <Reveal as="nav" aria-label="Themen der häufigen Fragen" className="mt-8">
            <p className="ov-overline text-ink-500">Direkt zum Thema</p>
            <ul className="mt-3 flex flex-wrap gap-2">
              {FAQ.map(({ id, thema, icon: Icon }) => (
                <li key={id}>
                  <a href={`#${id}`} className="inline-flex min-h-10 items-center gap-2 rounded-full bg-white px-3.5 text-[14px] font-medium text-ink-700 ring-1 ring-ink-200 transition-colors hover:bg-ov-50 hover:text-ov-800 hover:ring-ov-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500">
                    <Icon aria-hidden="true" className="h-4 w-4 text-ov-600" />
                    {thema}
                  </a>
                </li>
              ))}
            </ul>
          </Reveal>

          <Reveal delay={80} className="mt-8 hidden rounded-3xl bg-navy-950 p-6 text-white lg:block">
            <div className="flex items-start gap-4">
              <span aria-hidden="true" className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-white/10 text-ov-300">
                <MessageCircleQuestion className="h-5 w-5" />
              </span>
              <div className="min-w-0">
                <p className="font-display text-[18px] font-bold leading-snug">Ihre Frage ist nicht dabei?</p>
                <p className="mt-1.5 text-[14.5px] leading-relaxed text-white/75">Stellen Sie sie direkt in der Anfrage – im Feld „Ihre Nachricht“ ist Platz dafür.</p>
                <a href="#anfrage" className="group mt-4 inline-flex min-h-10 items-center gap-2 rounded-full bg-white px-4 text-[14px] font-semibold text-navy-950 transition-colors hover:bg-ov-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300 focus-visible:ring-offset-2 focus-visible:ring-offset-navy-950">
                  Zur Anfrage
                  <ArrowDown aria-hidden="true" className="h-4 w-4 transition-transform group-hover:translate-y-0.5" />
                </a>
              </div>
            </div>
          </Reveal>
        </div>

        <div>
          <ul className="space-y-3">
            {FAQ.map((f, i) => {
              const Icon = f.icon;
              return (
                <Reveal as="li" key={f.id} delay={i * 50}>
                  <details
                    id={f.id}
                    open={i === 0}
                    className="group scroll-mt-28 rounded-2xl bg-sand-50 ring-1 ring-ink-200/70 transition-[background-color,box-shadow] duration-300 open:bg-white open:shadow-e2 open:ring-ov-200 motion-reduce:transition-none"
                  >
                    <summary className="flex cursor-pointer list-none items-start gap-4 rounded-2xl p-5 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500 md:gap-5 md:p-6 [&::-webkit-details-marker]:hidden">
                      <span aria-hidden="true" className="mt-0.5 hidden h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white text-ov-600 ring-1 ring-ink-200/70 transition-colors group-open:bg-ov-600 group-open:text-white group-open:ring-ov-600 sm:flex">
                        <Icon className="h-[18px] w-[18px]" />
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="ov-overline block text-ov-700">{f.thema}</span>
                        <span className="mt-1 block font-display text-[17px] font-bold leading-snug text-ink-900 transition-colors group-hover:text-ov-800 md:text-[18.5px]">{f.q}</span>
                      </span>
                      <span aria-hidden="true" className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-white text-ink-700 ring-1 ring-ink-200 transition-transform duration-300 group-open:rotate-45 group-open:bg-ov-50 group-open:text-ov-700 group-open:ring-ov-200 motion-reduce:transition-none">
                        <Plus className="h-4 w-4" />
                      </span>
                    </summary>
                    <div className="px-5 pb-6 sm:pl-[4.75rem] md:px-6 md:pb-7 md:pl-[5.25rem] md:pr-16">
                      <p className="text-[16px] leading-relaxed text-ink-600">
                        <strong className="font-semibold text-ink-900">{f.kurz}</strong> {f.rest}
                      </p>
                      {f.mehr && (
                        <a href={f.mehr.href} className="group/mehr mt-4 inline-flex items-center gap-1.5 rounded text-[14.5px] font-semibold text-ov-700 underline-offset-4 hover:text-ov-800 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500">
                          {f.mehr.label}
                          <ArrowRight aria-hidden="true" className="h-4 w-4 transition-transform group-hover/mehr:translate-x-0.5" />
                        </a>
                      )}
                    </div>
                  </details>
                </Reveal>
              );
            })}
          </ul>

          {/* Unter lg: Hinweis unter der Liste statt in der Seitenspalte */}
          <p className="mt-6 flex flex-wrap items-center gap-x-2 gap-y-1 text-[15px] text-ink-600 lg:hidden">
            <MessageCircleQuestion aria-hidden="true" className="h-4 w-4 text-ov-600" />
            Ihre Frage ist nicht dabei?
            <a href="#anfrage" className="font-semibold text-ov-700 underline underline-offset-4 hover:text-ov-800">Stellen Sie sie in der Anfrage</a>
          </p>
        </div>
      </div>
    </Section>
  );
}

input.content:
// Anfrage über POST /api/anfrage – Höhepunkt der Seite: dunkle Bühne, helle Formularkarte.
// Reihenfolge mobil: Kopf → Formular → Ablauf (das Formular rutscht nicht unter die Falz-Liste).
import { ClipboardList, FileSearch, Handshake, ShieldCheck, KeyRound, Scale, MonitorPlay } from "lucide-react";
import Section from "@/components/ui/Section";
import { Eyebrow } from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import AnfrageMitDaten from "@/components/Gemeinschaft/AnfrageMitDaten";

// Schritt 2 beschreibt, was das Formular nach dem Absenden tatsächlich anzeigt (Vorgangsnummer, Status im Portal).
const ABLAUF = [
  { icon: ClipboardList, titel: "Sie schildern kurz Ihre Lage", text: "Modell, ungefähre Zählpunkte und Leistung genügen." },
  { icon: FileSearch, titel: "Sie erhalten eine Vorgangsnummer", text: "Direkt nach dem Absenden – den Stand können Sie im Portal verfolgen." },
  { icon: Handshake, titel: "Wir melden uns mit einem Vorschlag", text: "Passendes Paket und ein konkretes Angebot, offen kalkuliert." },
  { icon: MonitorPlay, titel: "Sie entscheiden", text: "Auf Wunsch zeigen wir die Plattform an Ihren eigenen Zahlen." },
];
const ZUSAGEN = [
  { icon: ShieldCheck, text: "Unverbindlich anfragen" },
  { icon: KeyRound, text: "Die Marktpartner-ID bleibt bei Ihrer Gemeinschaft" },
  { icon: Scale, text: "Auftragsverarbeitung nach Art. 28 DSGVO" },
];

// Dekor: Gemeinschaft als Netz – Knoten (Mitglieder) um einen Erzeuger, leise im Hintergrund.
function NetzDekor({ className }) {
  const knoten = [
    [60, 70], [190, 40], [300, 110], [90, 210], [250, 230], [340, 260], [150, 320], [30, 330],
  ];
  return (
    <svg aria-hidden="true" viewBox="0 0 380 380" fill="none" className={className}>
      {knoten.map(([x, y], i) => (
        <line key={`l${i}`} x1="190" y1="180" x2={x} y2={y} stroke="currentColor" strokeOpacity="0.18" strokeDasharray="3 6" />
      ))}
      <circle cx="190" cy="180" r="74" stroke="currentColor" strokeOpacity="0.1" />
      <circle cx="190" cy="180" r="140" stroke="currentColor" strokeOpacity="0.06" />
      {knoten.map(([x, y], i) => (
        <circle key={`k${i}`} cx={x} cy={y} r={i % 3 === 0 ? 5 : 3.5} fill="currentColor" fillOpacity="0.35" />
      ))}
      <circle cx="190" cy="180" r="16" fill="#f5a70f" fillOpacity="0.85" />
      <circle cx="190" cy="180" r="28" stroke="#f5a70f" strokeOpacity="0.35" />
    </svg>
  );
}

export default function Anfrage() {
  return (
    <Section
      data-abschnitt="anfrage"
      tone="navy"
      space="lg"
      id="anfrage"
      bare
      aria-labelledby="anfrage-titel"
      className="ov-verlauf-nacht ov-noise scroll-mt-24 overflow-hidden"
    >
      <div aria-hidden="true" className="ov-grid-bg pointer-events-none absolute inset-0 [mask-image:radial-gradient(70%_60%_at_20%_30%,#000,transparent)]" />
      <NetzDekor className="pointer-events-none absolute -left-24 top-10 hidden h-[420px] w-[420px] text-ov-300 opacity-60 xl:block" />

      <div className="ov-container relative grid gap-10 lg:grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)] lg:gap-x-16 lg:gap-y-12">
        {/* Kopf */}
        <Reveal className="lg:col-start-1 lg:row-start-1">
          <Eyebrow dark className="mb-4">Anfrage</Eyebrow>
          <h2 id="anfrage-titel" className="ov-h2 text-white">
            Gründen, wechseln oder <span className="ov-text-gradient">betreiben lassen</span>
          </h2>
          <p className="ov-lead mt-5 max-w-xl text-white/75">Erzählen Sie uns kurz, wo Ihre Gemeinschaft steht. Wir melden uns mit einem konkreten Vorschlag und Angebot.</p>
          <ul className="mt-8 flex flex-wrap gap-2">
            {ZUSAGEN.map(({ icon: Icon, text }) => (
              <li key={text} className="inline-flex min-h-10 items-center gap-2 rounded-full bg-white/[0.07] px-3.5 py-2 text-[14px] font-medium text-white/90 ring-1 ring-white/15">
                <Icon aria-hidden="true" className="h-4 w-4 shrink-0 text-ov-300" />
                {text}
              </li>
            ))}
          </ul>
        </Reveal>

        {/* Formular */}
        <Reveal dir="scale" className="relative lg:col-start-2 lg:row-span-2 lg:row-start-1">
          <div aria-hidden="true" className="absolute -inset-6 rounded-[2.75rem] bg-ov-500/20 blur-3xl" />
          <div className="relative overflow-hidden rounded-[2rem] bg-white text-ink-900 shadow-e4 ring-1 ring-white/20">
            <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-2 border-b border-ink-200/70 bg-gradient-to-r from-ov-50 to-white px-6 py-5 sm:px-8 md:px-10">
              <div className="min-w-0">
                <p className="font-display text-[20px] font-bold leading-tight text-ink-900">Ihre Anfrage</p>
                <p className="mt-1 text-[14px] text-ink-600">Pflicht sind nur Name, E-Mail und Ihre Einwilligung.</p>
              </div>
              <p className="inline-flex items-center gap-1.5 rounded-full bg-white px-3 py-1.5 text-[13px] font-semibold text-ov-800 ring-1 ring-ov-200">
                <ShieldCheck aria-hidden="true" className="h-4 w-4" /> Kostenlos und unverbindlich
              </p>
            </div>
            <div className="p-6 sm:p-8 md:p-10">
              <AnfrageMitDaten
                legende="Ihre Gemeinschaft oder Ihr Vorhaben"
                festeDaten={{ quelle: "energiegemeinschaften-software", land: "AT" }}
                zusatz={[
                  { name: "anliegen", label: "Worum geht es?", art: "chips", optionen: [{ id: "software", label: "Software nutzen" }, { id: "betrieb", label: "Betrieb abgeben" }, { id: "gruendung", label: "Gemeinschaft gründen" }, { id: "wechsel", label: "Anbieter wechseln" }] },
                  { name: "modell", label: "Modell", art: "select", optionen: [{ id: "offen", label: "Noch offen" }, { id: "eeg_lokal", label: "EEG lokal" }, { id: "eeg_regional", label: "EEG regional" }, { id: "beg", label: "BEG" }, { id: "gea", label: "GEA" }] },
                  { name: "zaehlpunkte", label: "Wie viele Zählpunkte? (Schätzung genügt)", art: "zahl", platzhalter: "z. B. 60" },
                  { name: "erzeugungKw", label: "Erzeugungsleistung in kW (Schätzung genügt)", art: "zahl", platzhalter: "z. B. 120" },
                ]}
                formular={{ typ: "energiegemeinschaft", felder: ["firma", "telefon", "plz", "nachricht"], button: "Unverbindlich anfragen" }}
              />
            </div>
          </div>
        </Reveal>

        {/* Ablauf */}
        <Reveal delay={80} className="lg:col-start-1 lg:row-start-2">
          <h3 className="ov-overline text-ov-300">Was nach dem Absenden passiert</h3>
          <ol className="relative mt-6">
            {ABLAUF.map(({ icon: Icon, titel, text }, i) => (
              <li key={titel} className="relative flex gap-4 pb-7 last:pb-0">
                {i < ABLAUF.length - 1 && (
                  <span aria-hidden="true" className="absolute left-[21px] top-12 bottom-1 w-px bg-gradient-to-b from-ov-400/60 to-white/10" />
                )}
                <span aria-hidden="true" className="relative flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-white/[0.08] text-ov-300 ring-1 ring-white/15">
                  <Icon className="h-5 w-5" />
                  <span className="absolute -right-1.5 -top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-sun-400 text-[11px] font-bold text-navy-950">{i + 1}</span>
                </span>
                <div className="min-w-0 pt-0.5">
                  <p className="font-display text-[17px] font-bold leading-snug text-white">
                    <span className="sr-only">Schritt {i + 1}: </span>
                    {titel}
                  </p>
                  <p className="mt-1 text-[15px] leading-relaxed text-white/70">{text}</p>
                </div>
              </li>
            ))}
          </ol>
        </Reveal>
      </div>
    </Section>
  );
}

